      "jb0v3": "毎朝KYと保護具チェック。安全の筆記とKY実演に合格しない生徒は実技に入れません。",
      "jb0v4": "朝礼 → KY → 段取り → 作業 → 片付け・清掃 → 終礼。1日を通して繰り返します。",
      "jb0v5": "時間厳守、あいさつ、報告、危険を見つけたらすぐ止める判断力。",
      "jbClass": "座学で学ぶ",
      "jb1n": "介護",
      "jb1v0": "高齢者の食事・入浴・移動の介助、見守り、記録。身体だけでなく気持ちに寄り添う仕事です。",
      "jb1v1": "敬語、体調を尋ねる表現、痛みや不調の聞き取り、記録に書く言葉。",
      "jb1v2": "バイタル・移乗・体位変換・清拭・見守り・申し送り。",
      "jb1v3": "感染対策、腰を痛めない介助姿勢、転倒防止、事故時の連絡。",
      "jb1v4": "申し送り → 朝の介助 → 食事 → 入浴・レク → 記録 → 申し送り。",
      "jb1v5": "ていねいな言葉づかい、報告の速さ、利用者と家族への敬意。",
      "jb2n": "農業",
      "jb2v0": "施設園芸・露地栽培の播種、定植、管理、収穫、選別、出荷。季節で作業が大きく変わります。",
      "jb2v1": "作物名、作業の指示、数量と規格、天候の言葉。",
      "jb2v2": "定植・摘果・追肥・選果・出荷規格・ハウス。",
      "jb2v3": "農薬の取り扱い、機械（管理機・運搬車）の安全、熱中症対策。",
      "jb2v4": "朝礼 → 収穫 → 選別・箱詰め → 出荷 → 片付け。",
      "jb2v5": "早朝の時間厳守、ていねいな手さばき、天候に合わせて動ける柔軟さ。",
      "jb3n": "製造",
      "jb3v0": "組立・加工・検査・梱包。決められた手順を、同じ品質で、同じ速さで続ける仕事です。",
      "jb3v1": "作業標準書を読む日本語、不良を報告する言い方、数量の伝え方。",
      "jb3v2": "工程・治具・ロット・不良・歩留まり・段取り替え。",
      "jb3v3": "回転部への巻き込み防止、保護具、非常停止ボタンの位置。",
      "jb3v4": "朝礼 → 段取り → ライン作業 → 検査 → 記録 → 清掃。",
      "jb3v5": "手順を勝手に変えない、異常に気づいたら止めて報告する。",
      "jb4n": "外食",
      "jb4v0": "調理補助、盛り付け、接客、レジ、清掃。速さと清潔さが同時に求められます。",
      "jb4v1": "接客のあいさつ、注文の聞き取り、アレルギーの確認、丁寧語。",
      "jb4v2": "仕込み・オーダー・ホール・バッシング・HACCP。",
      "jb4v3": "包丁と油の扱い、火傷防止、手洗いと衛生管理、アレルギー事故の防止。",
      "jb4v4": "仕込み → 開店 → ピーク対応 → 片付け → 清掃。",
      "jb4v5": "笑顔とあいさつ、忙しい時間帯でも手順を守る落ち着き。",
      "jb5n": "物流",
      "jb5v0": "入荷、仕分け、ピッキング、梱包、出荷。伝票と現物を正確に合わせる仕事です。",
      "jb5v1": "住所と地名の読み、数量と個数、伝票の日本語、確認の言い方。",
      "jb5v2": "入荷・検品・ピッキング・仕分け・パレット・伝票。",
      "jb5v3": "フォークリフトの周辺、台車の扱い、重量物の持ち上げ方、通路の確保。",
      "jb5v4": "朝礼 → 入荷検品 → 仕分け → ピッキング → 梱包 → 出荷。",
      "jb5v5": "数を間違えない正確さ、分からないときに確認する姿勢。",
      "jb6n": "清掃",
      "jb6v0": "建物・客室・共用部の清掃。決められた手順と時間で、確実に仕上げる仕事です。",
      "jb6v1": "薬剤名、場所の名前、点検表の日本語、報告の言い方。",
      "jb6v2": "日常清掃・定期清掃・ワックス・ポリッシャー・チェックリスト。",
      "jb6v3": "薬剤の混用禁止、転倒防止（濡れ床表示）、換気、手袋の着用。",
      "jb6v4": "点検 → 準備 → 清掃 → 仕上げ確認 → 記録 → 報告。",
      "jb6v5": "見えないところまで手を抜かない誠実さ、時間内に終える段取り力。",
      "jbNote": "※ 第1期に実技（体を動かす訓練）を行うのは建設分野です。介護・農業・製造・外食・物流・清掃は、仕事内容・使う日本語・専門用語・安全・仕事の流れを座学で学びます。実技の対象分野は、設備と講師が整いしだい順次広げます。",
      "h5": "③ 日本生活教育",
      "h5lead": "渡日してから困ることは、たいてい日本語ではなく「手続きとルール」です。実際の書類・アプリの画面・地図を見ながら、13項目を練習します。",
      "li0t": "交通ルール",
      "li0b": "自転車の左側通行、信号、踏切、ヘルメット。事故のときにすることも。",
