      "li1b": "燃える／燃えない／資源／粗大。曜日と時間、地域ごとの違い。",
      "li2t": "銀行",
      "li2b": "口座の開き方、ATMの使い方、送金、通帳とキャッシュカードの管理。",
      "li3t": "病院",
      "li3b": "保険証、受付、症状の伝え方、薬局。救急のときの119番。",
