      "li6t": "買い物",
      "li6b": "スーパーの表示、消費期限、レジ、レシート、返品のルール。",
      "li7t": "災害対応",
      "li7b": "地震・台風・大雨のとき。避難所、緊急速報、身を守る姿勢。",
      "li8t": "近所付き合い",
      "li8b": "あいさつ、騒音、共用部の使い方、ゴミ置き場のマナー。",
      "li9t": "公共マナー",
      "li9b": "電車内の通話、行列、喫煙場所、施設の使い方。",
      "li10t": "税金",
      "li10b": "所得税と住民税、給与明細の見方、年末調整。",
      "li11t": "年金",
      "li11b": "厚生年金、脱退一時金の考え方、手続きの窓口。",
      "li12t": "保険",
      "li12b": "健康保険、労災保険、雇用保険。ケガをしたときに使える制度。",
      "h6": "④ 社会人教育",
      "h6lead": "桜花がいちばん時間をかける教育です。日本の職場で評価されるのは、技能より先にこの12項目です。毎週木曜を固定コマにし、毎日の朝礼・終礼でも点数化して記録します。",
      "wk0t": "時間厳守",
      "wk0b": "5分前行動。遅れるときは必ず、遅れる前に連絡します。",
      "wk1t": "約束を守る",
      "wk1b": "できない約束はしない。できなくなったらすぐ言う。",
      "wk2t": "挨拶",
      "wk2b": "大きな声で先に。名前を呼んであいさつできるまで練習します。",
      "wk3t": "報告",
      "wk3b": "終わったら報告。報告して初めて仕事が終わると教えます。",
      "wk4t": "連絡",
      "wk4b": "遅刻・欠勤・体調不良は自分の口で。電話で練習します。",
      "wk5t": "相談",
      "wk5b": "分からないまま進めない。「わかりません」と言えるのが安全です。",
      "wk6t": "責任感",
      "wk6b": "自分の担当を最後まで持つ。言い訳より次の一手。",
      "wk7t": "チームワーク",
      "wk7b": "自分が早く終わったら、仲間の手を空けない。",
      "wk8t": "整理整頓",
      "wk8b": "道具は決めた場所へ。次に使う人が探さないように。",
      "wk9t": "清掃",
      "wk9b": "使った場所は使う前よりきれいに。毎日の当番で習慣にします。",
      "wk10t": "安全",
      "wk10b": "KY・指差呼称・保護具。危険を見つけたら止める判断を優先します。",
      "wk11t": "改善する力",
      "wk11b": "やりにくいことを言葉にして、やり方を変える提案までできるように。",
      "h7": "⑤ 就職教育",
      "h7lead": "面接に受かるためだけの教育ではありません。就職した後、契約や給与でつまずかないための知識まで教えます。",
      "em0t": "履歴書",
      "em0b": "日本式の書き方、写真、学歴・職歴の書き方、志望動機の組み立て。",
      "em1t": "自己紹介",
      "em1b": "30秒・1分・3分の3種類。何度も録音して直します。",
      "em2t": "面接",
      "em2b": "入室から退室まで。お辞儀・座り方・目線・答え方を型で覚えます。",
      "em3t": "企業研究",
      "em3b": "会社の事業、勤務地、職種、休日を自分で調べて質問を用意します。",
      "em4t": "雇用契約",
      "em4b": "契約書のどこを見るか。仕事内容・勤務地・休日・期間・解除の条件。",
      "em5t": "給与明細",
      "em5b": "総支給と手取りの違い。税・社会保険・寮費など控除項目の読み方。",
      "em6t": "労働条件",
      "em6b": "労働時間、休憩、残業と割増、有給休暇の基本的な考え方。",
      "em7t": "相談窓口",
      "em7b": "困ったときにどこへ連絡するか。会社・支援機関・公的窓口・桜花。",
      "em8t": "日本企業文化",
      "em8b": "上下関係、会議の進み方、飲み会、報連相の文化。誤解しやすい点を先に教えます。",
