      "f7v5": "フォークリフト資格の要否、勤務時間帯、冷凍・冷蔵の有無、繁忙期。",
      "f8n": "その他の特定技能対象分野",
      "f8v0": "自動車整備、造船・舶用工業、航空、漁業、飲食料品製造業ほか。",
      "f8v1": "分野ごとに定められた日本語要件。",
      "f8v2": "分野ごとの技能評価試験。区分と実施状況は変わります。",
      "f8v3": "ご相談に応じて、日本語と職場ルールの教育から準備します。",
      "f8v4": "分野ごとに適性項目を設定します。",
      "f8v5": "分野の受入れ可否、試験の実施状況、必要な実務経験。",
      "f9n": "技術・人文知識・国際業務の対象となり得る専門人材",
      "f9v0": "事務、通訳・翻訳、設計、IT関連など。単純作業は対象になりません。",
      "f9v1": "業務に必要な水準。学歴要件が中心になります。",
      "f9v2": "技能評価試験は原則不要（専門性と学歴で判断されます）。",
      "f9v3": "日本語と職場マナーの教育を担当します。専門分野の教育は行いません。",
      "f9v4": "学歴・職歴と業務内容の適合、日本語での説明力。",
      "f9v5": "業務内容と学歴の適合、在留資格の可否は貴社と専門家（行政書士等）でご確認ください。",
      "fn": "※ 仕事内容・試験・在留資格の要件は、日本政府の運用により変わります。断定できない内容は「個別に確認」と記載しています。最終的な可否は貴社と専門家、および出入国在留管理庁の判断によります。",
