      "h4": "候補者プロフィール（匿名の例）",
      "h4lead": "人材の質をイメージしていただくための例です。以下はすべて架空のサンプルで、実在の学生の情報ではありません。実際の候補者情報は、本人の同意と秘密保持契約を前提に、個別にお渡しします。",
      "cdis": "数値評価は、社内教育・面談上の参考評価であり、採用や業務能力を保証するものではありません。",
      "cpriv": "一般公開のこのページでは、氏名・顔が特定できる写真・電話番号・住所・パスポート・証明書番号は表示しません。",
      "h5": "企業へ提供する候補者情報",
      "h5lead": "本人の同意と必要な契約を前提として、次の情報を整理できる体制を目指しています。開示は3段階に分けています。",
