      "dn": "個人情報の保護、本人の同意、秘密保持を最優先します。本人の同意なく情報を第三者へ渡すことはありません。",
      "h6": "資格だけで選ばない",
      "h6lead": "JLPTやJFT-Basicの級だけで人材を判断しません。日本の職場でいちばん見られるのは、資格より先に「毎日どう過ごしたか」だからです。下記は運用の状況を正直に分けています。",
