      "e8b": "提出率と内容を記録する仕組みを準備中です。",
      "e9t": "作文",
      "e9b": "映像学習会の作文をためて、伸びを見えるようにしています。",
      "e10t": "面接",
      "e10b": "模擬面接を項目別に採点し、回ごとの変化を残す仕組みを準備中です。",
      "e11t": "責任感",
      "e11b": "班の役割と最後までやり切れたかを評価する基準を作成中です。",
