      "e13b": "やりにくいことを言葉にして改善提案までできたかを記録する予定です。",
      "en": "第1期の実績をもとに、記録の項目と基準を見直します。企業へお出しする評価は、確定した項目のみを使います。",
      "h7": "日本の企業・支援機関の皆さまへ",
      "h7lead": "許可や登録が必要な業務は、現在の許認可の状況に応じて「対応中」「提携機関を通じて対応」「準備中」「将来計画」を明記しています。未取得の許認可を取得済みとは表示しません。",
      "j0t": "外国人採用に関する事前相談",
      "j0b": "制度の全体像、期間、費用の考え方、よくある失敗をご説明します。無料です。",
