      "j3t": "候補者の募集",
      "j3b": "ネパール・ガイダコットで募集し、適性診断と面談を通じて選考します。",
      "j4t": "日本語・職業教育",
      "j4b": "N4／JFT-Basic A2 を目標に、日本語・職場ルール・安全・面接まで教育します。",
