      "j5b": "氏名・写真を伏せた形で、学歴・日本語・適性・出席率などを整理してお渡しします。",
      "j6t": "オンライン面接の調整",
      "j6b": "時差と回線を考慮して日程を調整し、通訳の同席も相談できます。",
      "j7t": "雇用条件の事前説明",
      "j7b": "給与・控除・寮費・勤務地・休日を、候補者本人と保護者に事前に説明します。",
      "j8t": "渡航前教育",
      "j8b": "生活・手続き・職場ルール・安全・相談先を渡日前に教育します。第1期で内容を固めています。",
      "j9t": "入社前の生活説明",
      "j9b": "住居・交通・買い物・病院・銀行の説明。貴社の地域情報をご提供いただけると精度が上がります。",
      "j10t": "入社後の相談・関係機関との連携",
