      "j11t": "在留資格の申請手続き",
      "svc_via": "提携機関を通じて対応",
      "j11b": "行政書士・登録支援機関など、必要な資格・登録を有する事業者との連携体制を整えた上で対応します。桜花が直接代行することはありません。",
      "j12t": "有料職業紹介としての人材紹介",
      "j12b": "許可が必要な業務です。現時点で許可は取得していません。取得時期をお約束することはできません。",
      "j13t": "登録支援機関としての支援業務",
