      "j15t": "人材派遣",
      "j15b": "許可が必要です。現時点で許可はありません。",
      "jlegal": "⚠ 現時点で ABAS GROUP は、有料職業紹介事業・登録支援機関・監理団体・労働者派遣事業のいずれの許認可も取得していません。これらに該当する業務は、許可・登録を有する事業者との連携体制を整えた上で対応するか、対応できません。許認可が必要な業務について、当社が直接手数料を受け取ることはありません。",
      "ctaJapan": "外国人受入れについて相談する",
      "h8": "ネパールの教育機関・送出機関の皆さまへ",
      "h8lead": "学生の取り合いではなく、育てる側どうしの分担を考えています。以下の形での連携をご相談いただけます。",
