      "n4b": "桜花が作成した教材・映像学習の枠組みを、条件を決めたうえで共有できます。",
      "n5t": "合同説明会",
      "n5b": "地域での合同説明会。費用と役割は個別に取り決めます。",
      "n6t": "候補者情報の共有",
      "n6b": "本人の同意と秘密保持契約を前提に、必要最小限の範囲で共有します。",
      "n7t": "日本企業との面接調整",
      "n7b": "面接の日程・通訳・評価項目のすり合わせを行います。",
      "n8t": "渡航前教育",
      "n8b": "生活・手続き・職場ルールの教育を分担、または桜花が受託する形も相談できます。",
      "n9t": "日本側支援機関との連携",
      "n9b": "許認可を持つ日本側の機関との橋渡しを、可能な範囲で行います。",
      "nterms": "提携条件・紹介料・収益分配などの具体的な条件は、一般公開していません。個別協議・契約によって決定します。",
      "nreqT": "提携先にお願いする基本条件",
      "nq0": "費用を学生へ正確に説明すること",
      "nq1": "虚偽の募集をしないこと",
      "nq2": "就職やビザを保証しないこと",
      "nq3": "本人の同意なく情報を共有しないこと",
