      "ctaNepal": "教育機関として提携を相談する",
      "h9": "日本へ送って終わりにしない",
      "h9lead": "渡航後の支援には、業務によって許認可が必要です。いま桜花としてできることと、許認可を取得したあとに行うことを分けて書きます。",
      "afNT": "いま桜花としてできること",
