      "afnow5": "卒業後10年を見据えた継続的な関わり",
      "afPT": "許認可を取得したあとに目指すこと（現時点では未取得）",
      "afplan0": "生活オリエンテーション（登録支援機関の業務）",
      "afplan1": "住居や行政手続きの案内",
      "afplan2": "銀行・携帯・病院に関する情報提供",
