      "afplan6": "転職やキャリアに関する相談",
      "afplan7": "問題発生時の関係機関への正式な取次ぎ",
      "afn": "⚠ 登録支援機関・監理団体・有料職業紹介・人材派遣は、いずれも現時点で許認可を取得していません。取得の時期をお約束することはできません。それまでの間は、許可・登録を有する事業者との連携体制を整えた上で対応するか、対応できないことを正直にお伝えします。",
      "h10": "外国人を採用する前に、企業が準備すること",
      "h10lead": "定着するかどうかは、本人の努力だけで決まりません。受け入れる側の準備が同じくらい効きます。外国人にだけ適応を求める職場では、日本人も辞めていきます。",
      "p0t": "仕事内容の明確化",
      "p0b": "何を、どこまで、どの手順でやるのか。契約書に書ける言葉にしておきます。",
      "p1t": "給与・控除・寮費の明確化",
      "p1b": "総支給と手取り、何がいくら引かれるかを、数字で説明できるようにします。",
      "p2t": "雇用契約書",
      "p2b": "母語または英語の説明があると、後のトラブルが大きく減ります。",
      "p3t": "安全教育",
      "p3b": "入社時の教育、保護具の支給、危険作業の手順。言葉が分からない前提で組み立てます。",
      "p4t": "指導担当者",
      "p4b": "誰に聞けばよいかを最初に決めます。担当が決まっていない職場は必ず混乱します。",
      "p5t": "相談窓口",
      "p5b": "困ったときの窓口を1つ決め、本人に伝えます。",
