      "f_thanks": "We have received your enquiry.",
      "f_idLabel": "Reference number",
      "f_thanks2": "Our staff will get back to you in turn. If it is urgent, please use the official email or WhatsApp.",
      "fn": "Only our staff see what you send. We will publish a target response time here once our team is settled; until then we can only say we reply in turn.",
      "h5": "Before you write to us",
      "h5lead": "The questions we get most often. If your answer is here, you will not have to wait for a reply. See the linked pages for detail.",
      "fg0t": "Students and parents",
      "more": "See more",
      "fq0_0q": "How much is the tuition?",
      "fq0_0a": "All courses cost 200,000 yen, paid in full in advance. There are no refunds.",
      "fq0_1q": "What does the 200,000 yen cover?",
      "fq0_1a": "Japanese, trade training, life and workplace rules, interview practice, exam preparation, materials, career management and free extra lessons.",
      "fq0_2q": "What extra costs are there?",
      "fq0_2a": "Exam fees, the medical check, certificates, notarised translation, the visa application and the flight come to roughly 100,000-250,000 yen, and it varies from person to person.",
      "fq0_3q": "Is the course different if I already have N4 or N5?",
      "fq0_3a": "Yes. With Japanese at N4 level you take the short employment course of 2-3 months; otherwise the main course of about 10 months.",
      "fq0_4q": "Can I enrol as a complete beginner?",
      "fq0_4a": "Yes. We start from hiragana.",
      "fq0_5q": "Do you guarantee a job?",
      "fq0_5a": "No. The employer decides. What we do is train and prepare you so that you can meet their conditions.",
      "fq0_6q": "Do you guarantee a visa?",
      "fq0_6a": "No. Residence status is granted by the Japanese government.",
      "fq0_7q": "How many months until I can go to Japan?",
      "fq0_7a": "About 10 months on the main course. It moves with your exam results and the employer's hiring schedule.",
      "fq0_8q": "What happens if I fail an exam?",
      "fq0_8a": "Extra lessons and repeating the course stay free. The exam fee itself is yours to pay.",
      "fq0_9q": "Are there refunds?",
      "fq0_9a": "There is no refund after enrolment. We go through this in writing with you before you enrol.",
      "fg1t": "Japanese employers",
      "fq1_0q": "Which fields are your people trained for?",
      "fq1_0a": "Construction above all, and you can also ask about caregiving, agriculture, manufacturing, food service, hospitality, cleaning and logistics.",
      "fq1_1q": "Can we see candidate profiles?",
      "fq1_1a": "Anonymous samples are public. Real candidate details are handed over only after a confidentiality agreement and the person's own consent.",
      "fq1_2q": "Do you assess anything besides Japanese qualifications?",
      "fq1_2a": "We report attendance, learning progress, interviews, daily conduct, safety awareness and job aptitude.",
      "fq1_3q": "Can interviews be held online?",
      "fq1_3a": "Yes. We arrange around the time difference and the connection, and an interpreter can sit in.",
      "fq1_4q": "Is there pre-departure training?",
      "fq1_4a": "Yes: how to read the employment terms, life in Japan, workplace rules and safety, all taught before departure. We are settling the content with the first intake.",
      "fq1_5q": "Do you support staff after they join?",
      "fq1_5a": "We keep answering questions as far as we are able. Support work that requires a licence is handled through licensed partners.",
      "fq1_6q": "Which licences do you currently hold?",
      "fq1_6a": "None of the following as of today: registered support organisation, supervising organisation, licensed recruitment, or staffing.",
      "fq1_7q": "At what point are your introduction terms disclosed?",
      "fq1_7a": "In the meeting itself. The actual terms are settled by individual discussion and contract.",
      "fg2t": "Partner organisations",
      "fq2_0q": "What kinds of partnership are possible?",
      "fq2_0a": "Student recruitment, Japanese teaching, vocational training, teacher training, shared materials, joint briefings, interview coordination and pre-departure training.",
      "fq2_1q": "Are your partnership terms published?",
      "fq2_1a": "No. They are settled by individual discussion and contract.",
      "fq2_2q": "How is candidate information shared?",
      "fq2_2a": "Only with the person's consent and a confidentiality agreement, and only the minimum needed.",
      "fq2_3q": "What are your rules on charging students?",
      "fq2_3a": "Costs must be explained to students accurately and no improper extra charges may be taken. That is a basic condition of any partnership with us.",
      "fq2_4q": "Can we share teaching content?",
      "fq2_4a": "Curriculum, pace, tests and materials can all be discussed. Terms are agreed case by case.",
      "fq2_5q": "How do you manage consent?",
      "fq2_5a": "We record whether consent was given and when, and information without consent is never passed to a third party.",
      "fqHint": "Choosing an enquiry type above narrows this list to that type.",
