      "heroTitle": "Let us think through your move to Japan, your hiring, or your partnership — together.",
      "heroLead": "Admissions, fees, courses, working in Japan, hiring from abroad, training and partnerships — ask us about whichever applies to you. We work in Japanese, Nepali and English."
