      "diffNote": "That said, we cannot claim OUKA is always cheaper. The employment route assumes that an employer hires you, that you pass the Japanese and skills tests, and that residence status is granted. If those conditions are not met, the cost remains without the outcome. Study is mainly for studying in Japan; the employment route is mainly for working in Japan. Do not compare two different purposes on price alone.",
