        "i2": "③ एक्लै निर्णय नगर्नुहोस् — कम्पनी, OUKA, सरकारी परामर्श केन्द्र। कदम चाल्नुअघि कसैसँग अनिवार्य सल्लाह लिनुहोस्।",
