      "ccw2": "राहदानी वा रेजिडेन्स कार्ड आफ्नो जिम्मामा लिन खोज्छन्",
      "ccw3": "गैरकानुनी लामो कामलाई सामान्य मानिन्छ (बिदाको दिन बताइँदैन)",
