      "exNote": "यी सामान्य उदाहरण हुन्। वास्तविक नतिजा मेहनत मात्र नभई परीक्षा, कम्पनीको निर्णय, निवास जाँच, स्वास्थ्य र पारिवारिक अवस्थामा भर पर्छ। कुनै पनि बाटोको ग्यारेन्टी छैन।",
      "h9": "९. तथ्यांकमा जापानमा रोजगारी",
