      "hubH": "उद्देश्यअनुसारको मार्गदर्शन",
      "hubL": "यो पृष्ठले समग्र चित्र दिन्छ। के चाहिएको हो थाहा भइसकेको भए, तलका विशेष पृष्ठमा जानुहोस्।",
      "hub0t": "नियुक्ति गर्ने सोच बनाइरहनुभएका जापानी कम्पनीहरूका लागि",
      "hub0d": "हामीले गर्ने र नगर्ने कुरा, शिक्षाको विषयवस्तु, उम्मेदवारको जानकारी, अन्तर्वार्ता, र नियुक्तिदेखि जापान प्रस्थानसम्मको प्रक्रिया।",
