      "h1": "हामीले खोजेको साझेदारी",
      "vq": "हामी मान्छे जापान पठाउने मात्र सम्बन्ध खोजेका छैनौं। नेपालमा भर्ना, भाषा र पेसागत शिक्षा, व्यक्तिको मूल्यांकन, कम्पनी अन्तर्वार्ता, प्रस्थान अघिको तालिम, र जापानमा जीवन तथा कामको सहयोग — यी सबै जोड्ने प्रणाली हाम्रो लक्ष्य हो।",
      "vb": "विद्यार्थी, पठाउने पक्ष, छनोट गर्ने कम्पनी र सहयोग संस्था — सबैले आवश्यक जानकारी हेर्न सक्ने पारदर्शी सहकार्यलाई महत्त्व दिन्छौं। एक पक्षले मात्र जानकारी राख्ने सम्बन्ध कतै न कतै भत्किन्छ।",
      "kpiT": "हामीले उपलब्धि मान्ने कुरा",
