      "kpi2t": "सुरक्षा",
      "kpi2b": "दुर्घटनाविना काम गरिरहेका छन् कि छैनन्।",
      "kpi3t": "विश्वास",
      "kpi3b": "कार्यस्थलमा नाम लिएर बोलाइन्छ र भर परिन्छ कि पर्दैन।",
      "kpi4t": "दीर्घकालीन रोजगारी",
      "kpi4b": "अर्को बसोबास हैसियतमा जान सके कि सकेनन्।",
      "vn": "संख्यालाई उपलब्धिको मापन बनाउँदैनौं। संख्या मात्र पछ्याउँदा कम्पनी र विद्यार्थी दुवैलाई घाटा हुन्छ।",
      "h2": "ABAS / OUKA सँग किन साझेदारी",
      "h2lead": "प्रत्येक बुँदामा अहिले उपलब्ध छ, तयारीमा छ, वा भविष्यको योजना हो भनी देखाइएको छ। नसक्ने कुरालाई सक्छु भन्दैनौं।",
      "svc_now": "अहिले उपलब्ध",
      "svc_part": "तयारीमा",
      "svc_plan": "भविष्यको योजना",
      "r0t": "दुवै पक्षको बुझाइ",
      "r0b": "हाम्रा प्रतिनिधि नेपालमा जन्मिएर जापानमा विद्यालय जीवन बिताउनुभयो र जापानी कम्पनी तथा समाजको अनुभव लिनुभयो। नेपाली पृष्ठभूमि र जापानी कार्यस्थलको संस्कृति — दुवै बुझेर शिक्षा र समन्वय गर्छौं।",
      "r1t": "जापानमा काममा केन्द्रित शिक्षा",
      "r1b": "जापानी भाषा मात्र होइन, रिपोर्ट-सम्पर्क-सल्लाह, समयको पालना, 5S, सुरक्षा र कार्यस्थलको शिष्टाचारसम्म सिकाउँछौँ। हरेक बिहीबार व्यावसायिक शिष्टाचारको निश्चित कक्षा, र हरेक बिहान KY (जोखिम पूर्वानुमान) बाट सुरु।",
      "r2t": "पेसा अनुसार शिक्षा",
      "r2b": "प्रत्येक पेसाका लागि चाहिने जापानी र कामको आधार सिकाइन्छ। पहिलो ब्याचमा व्यावहारिक तालिम निर्माण क्षेत्रमा हुन्छ। स्याहार, कृषि, उत्पादन, खाद्य सेवा, ढुवानी र सफाइ अहिले कक्षागत रूपमा आधार बनाइन्छ; व्यावहारिक तालिमको दायरा क्रमशः बढाइनेछ।",
      "r3t": "उम्मेदवार देखिने बनाउने",
      "r3b": "भाषा प्रमाणपत्र मात्र होइन — उपस्थिति, सिकाइको प्रगति, अन्तर्वार्ता, दैनिक आचरण, सुरक्षा चेतना र पेसागत उपयुक्तता मिलाएर बताउँछौँ। “N4 छ” होइन, “निर्माण उपयुक्तता ◯ अङ्क, उपस्थिति ९६%” भन्ने ढाँचामा।",
      "r4t": "पारदर्शी खर्च र सर्त",
