      "r5t": "प्रस्थान अघिको तालिम",
      "r5b": "प्रस्थानअघि सिकाउँछौँ — रोजगारीका सर्त कसरी पढ्ने, जापानको दैनिक जीवन (यातायात, फोहोर, बैंक, अस्पताल, नगरपालिका, विपद्), कार्यस्थलका नियम, सुरक्षा, र अप्ठ्यारो पर्दा कसरी सल्लाह लिने। विषयवस्तु पहिलो ब्याचमार्फत टुङ्ग्याइँदै छ।",
      "r6t": "जापानी पक्षसँग निरन्तर सहकार्य",
      "r6b": "काममा लागेपछि पनि, रोजगारदाता र सहयोग संस्थासँग आवश्यक जानकारी साझा गरी समस्या चाँडै पत्ता लगाउने लक्ष्य राख्छौँ। समन्वयको दायरा र तरिका सम्झौता र सम्बन्धित व्यक्तिको सहमतिका आधारमा तय हुन्छ।",
      "r7t": "दीर्घकालीन सहयोग संरचना",
      "r7b": "दीर्घकालमा दर्ता भएको सहयोग संस्था, शुल्क लिने रोजगार सिफारिस, अनुगमन संस्था र जनशक्ति पठाउने व्यवसाय मिलाएर एकीकृत व्यवस्था बनाउने लक्ष्य छ। यीमध्ये कुनै पनि अहिलेसम्म प्राप्त गरिएको छैन; विद्यालय सञ्चालन र पहिलो ब्याच स्थिर भएपछि क्रमशः विचार गरिनेछ।",
