      "f6v5": "कामको दायरा, प्रयोग हुने रसायन, एक्लै काम गर्नुपर्छ कि पर्दैन, र यात्रा गर्नुपर्छ कि पर्दैन।",
      "f7n": "लजिस्टिक्स",
      "f7v0": "भित्र्याउने, जाँच, छुट्याउने, टिप्ने, प्याक गर्ने, पठाउने। कागज र सामान मिलाउने।",
      "f7v1": "JFT-Basic A2 वा JLPT N4 स्तर। ठेगाना, परिमाण र बिलको जापानी।",
      "f7v2": "लागू हुने बसोबास हैसियत र क्षेत्रका सर्त छुट्टाछुट्टै पुष्टि गरिन्छ।",
      "f7v3": "कक्षामा गन्ने तरिका, पुष्टि गर्ने तरिका, फोर्कलिफ्ट वरिपरिको सुरक्षा, र गह्रौँ सामान चलाउने तरिका।",
      "f7v4": "गन्तीमा गल्ती नगर्ने शुद्धता, र थाहा नभएको बेला सोध्ने बानी।",
      "f7v5": "फोर्कलिफ्ट लाइसेन्स चाहिन्छ कि चाहिँदैन, कामको समय, फ्रोजन/चिस्यान कक्ष छ कि छैन, र व्यस्त मौसम।",
      "f8n": "अन्य SSW क्षेत्र",
      "f8v0": "सवारी मर्मत, जहाज निर्माण र सामुद्रिक उद्योग, विमानसेवा, मत्स्यपालन, खाद्य तथा पेय उत्पादन आदि।",
      "f8v1": "प्रत्येक क्षेत्रका लागि तोकिएको जापानी भाषा सर्त।",
      "f8v2": "प्रत्येक क्षेत्रको सिप मूल्याङ्कन परीक्षा। वर्गीकरण र परीक्षा सञ्चालनको अवस्था परिवर्तन हुन्छ।",
      "f8v3": "अनुरोधअनुसार, जापानी भाषा र कार्यस्थलका नियमको शिक्षाबाट तयारी गर्छौं।",
      "f8v4": "प्रत्येक क्षेत्रका लागि उपयुक्तताका बुँदा तय गरिन्छ।",
      "f8v5": "क्षेत्रले स्वीकार गर्न सक्छ कि सक्दैन, परीक्षा सञ्चालन भइरहेको छ कि छैन, र चाहिने व्यावहारिक अनुभव।",
      "f9n": "सम्भावित Engineer / Specialist",
      "f9v0": "कार्यालय, दोभाषे र अनुवाद, डिजाइन, IT आदि। साधारण श्रम कार्य समावेश हुँदैन।",
      "f9v1": "कामले माग्ने स्तर। शैक्षिक योग्यताको सर्त मुख्य हुन्छ।",
      "f9v2": "सामान्यतया सिप मूल्याङ्कन परीक्षा आवश्यक हुँदैन (विशेषज्ञता र शैक्षिक योग्यताबाट मूल्याङ्कन)।",
      "f9v3": "जापानी भाषा र कार्यस्थल शिष्टाचारको शिक्षा हामी गर्छौं। विशेषज्ञ विषयको शिक्षा गर्दैनौँ।",
      "f9v4": "शैक्षिक योग्यता र कामको अनुभव कामसँग कति मिल्छ, र जापानीमा व्याख्या गर्न सक्ने क्षमता।",
      "f9v5": "कामको प्रकृति र शैक्षिक योग्यताको मेल, तथा बसोबास हैसियत सम्भव छ कि छैन — यी कुरा तपाईंको कम्पनी र विशेषज्ञ (行政書士 आदि) सँग पुष्टि गर्नुहोला।",
      "fn": "सूचना: काम, परीक्षा र अनुमतिका सर्त जापान सरकारको नीतिअनुसार परिवर्तन हुन्छ। निश्चित भन्न नसकिने ठाउँमा त्यसै लेखिएको छ। अन्तिम निर्णय तपाईं, विज्ञ र अध्यागमन एजेन्सीको हो।",
