      "h4lead": "उम्मेदवारको स्तर बुझाउन उदाहरण। तलका सबै काल्पनिक नमुना हुन्, वास्तविक विद्यार्थी होइनन्। वास्तविक जानकारी व्यक्तिको सहमति र गोपनीयता सम्झौतापछि छुट्टै दिइन्छ।",
      "cdis": "अंकहरू हाम्रो शिक्षण र अन्तर्वार्ताका आन्तरिक सन्दर्भ मूल्यांकन हुन्। छनोट उपयुक्तता वा कार्यक्षमताको ग्यारेन्टी होइन।",
      "cpriv": "यो सार्वजनिक पृष्ठमा नाम, चिनिने फोटो, फोन नम्बर, ठेगाना, राहदानी वा प्रमाणपत्र नम्बर देखाइँदैन।",
      "h5": "तपाईंलाई दिन सक्ने जानकारी",
