      "p8t": "उत्पीडन रोकथाम",
      "p8b": "सिकाउनु र गाली गर्नु फरक कुरा हुन्। व्यवस्थापकका लागि जाँच गर्न सिफारिस गर्छौं।",
      "p9t": "काम सुरु भएपछि नियमित जाँच",
      "p9b": "पहिलो ३ महिना महिनामा एकपटक, त्यसपछि ३ महिनामा एकपटक। चाँडै थाहा पाए समस्या सानै रहन्छ।",
      "h11": "राम्रो साझेदारी र सावधानीका संकेत",
      "h11lead": "यसले कुनै निश्चित कम्पनी वा संस्थालाई संकेत गर्दैन। सामान्य बुँदा हुन्, र हामी आफैं पनि यही मापदण्डले जाँचिन्छौं भन्ने ठान्छौं।",
      "gbGT": "राम्रो साझेदारीका संकेत",
