      "gbg3": "लिखित सम्झौता छ",
      "gbg4": "विद्यार्थीको आफ्नै इच्छा पुष्टि गर्छन्",
      "gbg5": "समस्या आउँदा सँगै मिलेर समाधान गर्न खोज्छन्",
      "gbg6": "कति जना लिए भन्दा पनि लिएपछि कति टिके भन्नेमा ध्यान दिन्छन्",
      "gbBT": "सावधानीका संकेत",
