        "b0": "यस पृष्ठको तल्लो भागको फारम वा फोनबाट सम्पर्क गर्नुहोस्। संस्थाको प्रकार र उद्देश्य बताउनुहोस्।",
        "t1": "अनलाइन वा आमनेसामने कुराकानी",
