      "h8": "ग्यारेन्टी नगर्ने कुरा",
      "h8lead": "पैसा तिरेर पाइने कुरा होइन। यीमध्ये कुनै पनि OUKA ले निर्णय गर्ने कुरा होइन, त्यसैले ग्यारेन्टी दिन सक्दैनौं। ग्यारेन्टी दिन्छु भन्ने विद्यालय वा बिचौलियासँग सावधान रहनुहोस्।",
