      "h4lead": "अवधि पेसा, परीक्षा र बसोबास योग्यताको जाँचको अवस्थाअनुसार फरक पर्छ। निश्चित दिनको वाचा गर्न सकिँदैन।",
      "fl0t": "१. परामर्श",
      "fl0d": "आवश्यक पेसा, संख्या, समय र सर्त बताउनुहोस्। अनलाइन भए पनि हुन्छ।",
      "fl1t": "२. उम्मेदवारको प्रस्ताव",
      "fl1d": "सर्त मिल्ने विद्यार्थीको सिकाइ अभिलेख र योग्यता मूल्यांकन पठाइन्छ (सम्बन्धित व्यक्तिको सहमतिको दायरामा)।",
      "fl2t": "३. अनलाइन अन्तर्वार्ता",
