      "fl4t": "५. प्रस्थानअघि थप तालिम",
      "fl4d": "तय भएको पेसा र कम्पनीअनुसार आवश्यक जापानी भाषा र कामको तालिम थपिन्छ।",
      "fl5t": "६. परीक्षा र बसोबास योग्यताको प्रक्रिया",
      "fl5d": "आवश्यक परीक्षाका लागि सहयोग गरिन्छ। बसोबास योग्यताको आवेदन, आवश्यक योग्यता भएको सञ्चालकसँग सहकार्यको व्यवस्था मिलाएपछि मात्र अगाडि बढाइन्छ।",
