      "fmain0": "निर्माण (इलेक्ट्रिकल, सिभिल, स्क्याफोल्डिङ, प्लास्टरिङ, भत्काउने काम, पाइपिङ, उचाल्ने काम, सामान्य निर्माण आदि)",
      "foth0": "स्याहार",
