      "foth6": "अटो मर्मत",
      "foth7": "लजिस्टिक्स",
      "fNote": "पेसाअनुसार चाहिने परीक्षा र बसोबास योग्यता फरक हुन्छ। विस्तृत जानकारी 特定技能 (Specified Skilled Worker) पृष्ठमा हेर्नुहोस्।",
      "fLink1": "निर्माण क्षेत्रको पृष्ठ हेर्नुहोस्",
      "fLink2": "特定技能 (Specified Skilled Worker) बारे हेर्नुहोस्",
