      "fq0a": "भर्ना हुँदा अधिकांश हिरागानाबाट सुरु गर्छन्। तालिमपछि अभिवादन, जवाफ, औजारका नाम, कामको निर्देशन बुझ्ने र खतराको रिपोर्ट गर्न सक्ने अवस्थालाई लक्ष्य राखिन्छ। अन्तर्वार्तामा आफैं जाँच्नुहोस्।",
      "fq1q": "अनुभवी व्यक्ति छन्?",
      "fq1a": "नेपालमा निर्माण क्षेत्रमा काम गरेकाहरू पनि छन्। अनुभव छ कि छैन भन्ने प्रत्येक उम्मेदवारअनुसार बताइन्छ। अनुभव नभएकाले पनि तालिम स्थलमा औजार चलाउनेदेखि सिक्छन्।",
      "fq2q": "कति जनालाई परिचय गराउन सक्नुहुन्छ?",
      "fq2a": "भर्नाको अवस्थामा भर पर्छ। निश्चित संख्याको वाचा गर्न सक्दैनौं। चाहिने समय र संख्या बताउनुभयो भने, अहिलेको अवस्थामा सम्भव छ कि छैन इमानदारीपूर्वक जवाफ दिन्छौं।",
      "fq3q": "खर्च कति लाग्छ?",
      "fq3a": "पेसा, बसोबास योग्यता र सहयोग कसलाई जिम्मा दिइन्छ भन्नेअनुसार फरक पर्ने भएकाले एउटै रकम सार्वजनिक गरिँदैन। परामर्शका बेला आवश्यक खर्चको विवरण बुझाइन्छ।",
      "fq4q": "特定技能 हो कि 育成就労?",
      "fq4a": "तपाईंको आवश्यकता र सम्बन्धित व्यक्तिको अवस्थामा भर पर्छ। दुई प्रणालीको फरक 特定技能 (Specified Skilled Worker) पृष्ठमा व्याख्या गरिएको छ।",
      "fq5q": "भर्ना गरेपछि छाडेर जान्छन् कि भन्ने चिन्ता छ",
      "fq5a": "जापान जानुअघि कामको विवरण, तलब, जीवनयापन खर्च र बासका नियम आफ्नै भाषामा ठिक-ठिक बुझाउनुलाई हामी महत्त्व दिन्छौं। \"सुनेको भन्दा फरक रहेछ\" भन्ने अवस्था हटाउनु नै काम छाड्ने समस्या रोक्ने उत्तम उपाय हो भन्ने हाम्रो विश्वास छ।",
      "ctaH": "निर्माण क्षेत्रका जनशक्तिबारे परामर्श गर्नुहोस्",
      "ctaL": "\"यस्तो काम गर्न सक्ने व्यक्ति चाहियो\" भन्दा पनि पुग्छ।",
