      "ctaB2": "अनलाइन भेटघाट अनुरोध गर्नुहोस्",
      "hero": "निर्माण साइटमा काम गर्न सक्ने जनशक्ति नेपालमा तयार पार्दैछौं।",
      "heroLead": "\"जापानी बोल्न सक्छ तर साइटमा काम गर्न सक्दैन\" भन्ने अवस्था हटाउन बनेको विद्यालय हो। OUKA ले निर्माण क्षेत्रमा केन्द्रित भई भाषा, काम, सुरक्षा र कार्यस्थलका नियम जापान जानुअघि सिकाउँछ। भर्ना अधिकारीले आफैं मूल्यांकन गर्न सकून् भनेर हामी सिकाउने कुरा जस्ताको तस्तै सार्वजनिक गर्छौं।"
